@model Umbraco.Bench.Umbraco.Models.Blocks.ImageBlockModel

<figure class="my-6">
    <img src="@Model.ImageUrl" alt="@Model.Caption" class="w-full h-auto rounded-lg" />
    @if (!string.IsNullOrEmpty(Model.Caption))
    {
        <figcaption class="mt-2 text-center text-sm text-gray-500">@Model.Caption</figcaption>
    }
</figure>

@model Umbraco.Bench.Umbraco.Models.Blocks.QuoteBlockModel

<blockquote class="my-6 border-l-4 border-gray-300 pl-4 italic">
    <p class="text-lg">@Model.Quote</p>
    @if (!string.IsNullOrEmpty(Model.Attribution))
    {
        <footer class="mt-2 text-sm text-gray-600">— @Model.Attribution</footer>
    }
</blockquote>

